function smoothPath(points) {
  if (points.length < 2) return "";
  let d = `M ${points[0].x.toFixed(1)} ${points[0].y.toFixed(1)}`;
  for (let i = 0; i < points.length - 1; i++) {
    const p0 = points[i === 0 ? i : i - 1];
    const p1 = points[i];
    const p2 = points[i + 1];
    const p3 = points[i + 2 < points.length ? i + 2 : i + 1];
    const cp1x = p1.x + (p2.x - p0.x) / 6;
    const cp1y = p1.y + (p2.y - p0.y) / 6;
    const cp2x = p2.x - (p3.x - p1.x) / 6;
    const cp2y = p2.y - (p3.y - p1.y) / 6;
    d += ` C ${cp1x.toFixed(1)} ${cp1y.toFixed(1)}, ${cp2x.toFixed(1)} ${cp2y.toFixed(1)}, ${p2.x.toFixed(1)} ${p2.y.toFixed(1)}`;
  }
  return d;
}

function niceMax(v) {
  if (v <= 0) return 100;
  const exp = Math.pow(10, Math.floor(Math.log10(v)));
  const norm = v / exp;
  let nice;
  if (norm <= 1) nice = 1;
  else if (norm <= 2) nice = 2;
  else if (norm <= 5) nice = 5;
  else nice = 10;
  return nice * exp;
}

function shortFmt(n) {
  return `$${Math.round(n).toLocaleString("es-AR")}`;
}

function MiniChart({ chart, maxVal }) {
  const W = 600, H = 220, padL = 50, padR = 10, padT = 10, padB = 24;
  const n = chart.length;
  const plotW = W - padL - padR;
  const plotH = H - padT - padB;
  const top = niceMax(maxVal);
  const x = (i) => padL + (n === 1 ? 0 : (i / (n - 1)) * plotW);
  const y = (v) => padT + plotH - (v / top) * plotH;
  const baseline = padT + plotH;

  const ingPts = chart.map((p, i) => ({ x: x(i), y: y(p.ingresos) }));
  const gasPts = chart.map((p, i) => ({ x: x(i), y: y(p.gastos) }));

  const ingLine = smoothPath(ingPts);
  const gasLine = smoothPath(gasPts);
  const ingArea = `${ingLine} L ${x(n - 1).toFixed(1)} ${baseline} L ${x(0).toFixed(1)} ${baseline} Z`;
  const gasArea = `${gasLine} L ${x(n - 1).toFixed(1)} ${baseline} L ${x(0).toFixed(1)} ${baseline} Z`;

  const yTicks = [0, top * 0.25, top * 0.5, top * 0.75, top];
  const xTickDays = [1, 5, 10, 15, 20, 25, 30].filter((d) => d <= n);

  return (
    <svg viewBox={`0 0 ${W} ${H}`} width="100%" height={220}>
      <defs>
        <linearGradient id="ingGrad" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor="#3ED17F" stopOpacity="0.55" />
          <stop offset="100%" stopColor="#3ED17F" stopOpacity="0.04" />
        </linearGradient>
      </defs>
      {yTicks.map((t, idx) => (
        <line key={idx} x1={padL} x2={W - padR} y1={y(t)} y2={y(t)} stroke="rgba(255,255,255,0.06)" strokeWidth="1" />
      ))}
      {yTicks.map((t, idx) => (
        <text key={idx} x={padL - 8} y={y(t) + 4} textAnchor="end" fontSize="11" fill="#7D828C">
          {shortFmt(t)}
        </text>
      ))}
      {xTickDays.map((d) => (
        <text key={d} x={x(d - 1)} y={H - 4} textAnchor="middle" fontSize="11" fill="#7D828C">
          {d}
        </text>
      ))}
      <path d={ingArea} fill="url(#ingGrad)" />
      <path d={gasArea} fill="#454B57" fillOpacity="0.55" />
      <path d={gasLine} fill="none" stroke="#9AA0AC" strokeWidth="1.5" />
      <path d={ingLine} fill="none" stroke="#3ED17F" strokeWidth="2.5" />
    </svg>
  );
}

function StatCard({ icon: Icon, iconBg, label, labelColor, value }) {
  return (
    <div style={{ ...CARD, background: "#12151B", border: "none", padding: "14px 12px", display: "flex", alignItems: "center", gap: 10 }}>
      <div style={{ width: 34, height: 34, borderRadius: "50%", background: iconBg, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
        <Icon size={16} color="#fff" strokeWidth={2.5} />
      </div>
      <div>
        <div style={{ fontSize: 11.5, color: labelColor, fontWeight: 600, marginBottom: 2 }}>{label}</div>
        <div style={{ fontSize: 14.5, fontWeight: 700, color: "#fff" }}>{value}</div>
      </div>
    </div>
  );
}

